class Cart:
    def __init__(self):
        self.lines = {}

    def add(self, name, price, qty=1):
        if name in self.lines:
            self.lines[name][1] += qty
        else:
            self.lines[name] = [price, qty]

    def remove(self, name):
        if name in self.lines:
            del self.lines[name]
            return True
        return False

    def total(self):
        return sum(p * q for p, q in self.lines.values())

    def total_with_coupon(self, percent):
        return round(self.total() * (100 - percent) / 100, 1)

    def items(self):
        return list(self.lines)

